// Package webhook implements GitHub webhook signature verification, push event
// parsing, and branch routing for api.
package webhook

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"regexp"
	"strings"
)

// PushEvent is the subset of a GitHub push event payload that adapter-service needs.
type PushEvent struct {
	Ref        string     `json:"ref"`
	After      string     `json:"after"`
	Repository Repository `json:"repository"`
	Commits    []Commit   `json:"commits"`
}

// Repository holds repository identity from the push payload.
type Repository struct {
	FullName string `json:"full_name"`
	HTMLURL  string `json:"html_url"`
	CloneURL string `json:"clone_url"`
}

// Commit holds the changed file lists from a single push commit.
type Commit struct {
	Added    []string `json:"added"`
	Modified []string `json:"modified"`
	Removed  []string `json:"removed"`
}

// BranchKind classifies the branch from a push event.
type BranchKind int

const (
	BranchIgnored BranchKind = iota
	BranchBase               // base branch (e.g. "main")
	BranchFeature            // feature/<feature-id>
	BranchTask               // feature/<feature-id>-T<n>
)

// BranchInfo contains the parsed branch information.
type BranchInfo struct {
	Kind      BranchKind
	Branch    string
	FeatureID string
	TaskID    string
}

// featurePathRe matches docs/features/<feature-id>/ path prefixes.
var featurePathRe = regexp.MustCompile(`^docs/features/([^/]+)/`)

const defaultBranchPattern = "feature/{feature_id}-{work_id}"

var workIDRe = regexp.MustCompile(`^T\d+$`)

// VerifySignature checks the X-Hub-Signature-256 header against the request body.
// Returns an error if the signature is missing or invalid.
func VerifySignature(secret string, header string, body []byte) error {
	if secret == "" {
		return fmt.Errorf("GITHUB_WEBHOOK_SECRET is required")
	}
	const prefix = "sha256="
	if !strings.HasPrefix(header, prefix) {
		return fmt.Errorf("missing or malformed X-Hub-Signature-256 header")
	}
	gotHex := strings.TrimPrefix(header, prefix)
	mac := hmac.New(sha256.New, []byte(secret))
	mac.Write(body)
	wantHex := hex.EncodeToString(mac.Sum(nil))
	if !hmac.Equal([]byte(gotHex), []byte(wantHex)) {
		return fmt.Errorf("webhook signature mismatch")
	}
	return nil
}

const maxWebhookBodyBytes = 10 << 20 // 10 MiB

// ReadBody reads the request body up to maxWebhookBodyBytes without verifying the signature.
// Returns raw bytes. The caller must not call r.Body.Read again.
func ReadBody(r *http.Request) ([]byte, error) {
	body, err := io.ReadAll(io.LimitReader(r.Body, maxWebhookBodyBytes))
	if err != nil {
		return nil, fmt.Errorf("read webhook body: %w", err)
	}
	return body, nil
}

// ReadAndVerify reads the request body and verifies the GitHub HMAC signature.
// Returns the raw body bytes on success. The caller must not call r.Body.Read again.
func ReadAndVerify(r *http.Request, secret string) ([]byte, error) {
	body, err := io.ReadAll(io.LimitReader(r.Body, maxWebhookBodyBytes))
	if err != nil {
		return nil, fmt.Errorf("read webhook body: %w", err)
	}
	sig := r.Header.Get("X-Hub-Signature-256")
	if err := VerifySignature(secret, sig, body); err != nil {
		return nil, err
	}
	return body, nil
}

// ParsePushEvent parses raw push event JSON into a PushEvent.
func ParsePushEvent(data []byte) (*PushEvent, error) {
	var ev PushEvent
	if err := json.Unmarshal(data, &ev); err != nil {
		return nil, fmt.Errorf("parse push event: %w", err)
	}
	return &ev, nil
}

// BranchFromRef strips the "refs/heads/" prefix from a git ref.
func BranchFromRef(ref string) string {
	return strings.TrimPrefix(ref, "refs/heads/")
}

// ClassifyBranch returns the BranchKind and parsed identifiers for the given branch name.
func ClassifyBranch(branch, baseBranch string, branchPatterns ...string) BranchInfo {
	if branch == "" {
		return BranchInfo{Kind: BranchIgnored}
	}
	if branch == baseBranch {
		return BranchInfo{Kind: BranchBase, Branch: branch}
	}

	branchPattern := defaultBranchPattern
	if len(branchPatterns) > 0 && strings.TrimSpace(branchPatterns[0]) != "" {
		branchPattern = strings.TrimSpace(branchPatterns[0])
	}

	if info, ok := classifyByPattern(branch, branchPattern, true); ok {
		return info
	}
	if featurePattern := featurePatternFromTaskPattern(branchPattern); featurePattern != "" {
		if info, ok := classifyByPattern(branch, featurePattern, false); ok {
			return info
		}
	}
	return BranchInfo{Kind: BranchIgnored, Branch: branch}
}

func classifyByPattern(branch, pattern string, task bool) (BranchInfo, bool) {
	re, names, ok := branchPatternRegexp(pattern)
	if !ok {
		return BranchInfo{}, false
	}
	matches := re.FindStringSubmatch(branch)
	if matches == nil {
		return BranchInfo{}, false
	}
	values := map[string]string{}
	for i, name := range names {
		values[name] = matches[i+1]
	}
	info := BranchInfo{Branch: branch, FeatureID: values["feature_id"]}
	if task {
		info.Kind = BranchTask
		info.TaskID = values["work_id"]
		if info.FeatureID == "" || info.TaskID == "" {
			return BranchInfo{}, false
		}
		if !workIDRe.MatchString(info.TaskID) {
			return BranchInfo{}, false
		}
		return info, true
	}
	info.Kind = BranchFeature
	if info.FeatureID == "" {
		return BranchInfo{}, false
	}
	return info, true
}

func branchPatternRegexp(pattern string) (*regexp.Regexp, []string, bool) {
	var b strings.Builder
	var names []string
	for i := 0; i < len(pattern); {
		switch {
		case strings.HasPrefix(pattern[i:], "{feature_id}"):
			b.WriteString("(.+)")
			names = append(names, "feature_id")
			i += len("{feature_id}")
		case strings.HasPrefix(pattern[i:], "{work_id}"):
			b.WriteString("([^/]+)")
			names = append(names, "work_id")
			i += len("{work_id}")
		default:
			b.WriteString(regexp.QuoteMeta(pattern[i : i+1]))
			i++
		}
	}
	if len(names) == 0 {
