func featurePatternFromTaskPattern(pattern string) string {
	idx := strings.Index(pattern, "{work_id}")
	if idx < 0 {
		return ""
	}
	prefix := pattern[:idx]
	prefix = strings.TrimRight(prefix, "/-_.")
	if slash := strings.LastIndex(prefix, "/"); slash >= 0 {
		tail := prefix[slash+1:]
		if !strings.Contains(tail, "{feature_id}") {
			prefix = prefix[:slash]
		}
	}
	if !strings.Contains(prefix, "{feature_id}") {
		return ""
	}
	return prefix
}

// TouchedFeatureIDs extracts unique feature IDs from docs/features/<feature-id>/ paths
// across all commits in the push event.
func TouchedFeatureIDs(ev *PushEvent) []string {
	seen := make(map[string]struct{})
	var ids []string
	for _, c := range ev.Commits {
		for _, paths := range [][]string{c.Added, c.Modified, c.Removed} {
			for _, p := range paths {
				m := featurePathRe.FindStringSubmatch(p)
				if m == nil {
					continue
				}
				fid := m[1]
				if _, dup := seen[fid]; !dup {
					seen[fid] = struct{}{}
					ids = append(ids, fid)
				}
			}
		}
	}
	return ids
}

